  gap: 8px;
  padding: 8px 12px;
  border-radius: 8px;
  font-size: 12px;
  font-weight: 600;
  color: var(--text-primary);
  background: transparent;
  border: none;
  cursor: pointer;
  transition: all 0.15s ease;
  text-align: left;
}
.link-action-btn:hover {
  background-color: rgba(197, 160, 89, 0.12);
  color: var(--accent-gold-dark);
}

#popup-notifications .b2b-toast {
  align-items: center;
  width: fit-content;
  max-width: min(92vw, 24rem);
  border: 1px solid rgba(197, 160, 89, 0.55);
  border-radius: 999px;
  background: var(--bg-bubble-self);
  color: var(--accent-gold);
  box-shadow: 0 12px 32px rgba(10, 26, 58, 0.22);
}

#popup-notifications .b2b-toast .b2b-toast-icon {
  width: 2rem;
  height: 2rem;
  flex: 0 0 2rem;
  border: 1px solid var(--accent-gold-glow);
  border-radius: 50%;
  background: rgba(197, 160, 89, 0.12);
  color: var(--accent-gold);
}

#popup-notifications .b2b-toast .b2b-toast-title,
#popup-notifications .b2b-toast .b2b-toast-message {
  color: var(--accent-gold);
}

#sidebar-panel,
#chat-panel-container,
#info-drawer-panel {
  color: var(--text-primary);
}

#sidebar-panel,
#info-drawer-panel {
  background-color: var(--bg-card);
}

#chat-panel-container,
#chat-panel {
  background-color: var(--bg-main);
}

#chat-panel > header,
#sidebar-panel > div:first-child {
  border-color: var(--border-subtle);
}

button,
[role="button"] {
  transition-property: color, background-color, border-color, box-shadow, transform, opacity;
  transition-duration: 160ms;
  transition-timing-function: ease;
}

button:focus-visible,
[role="button"]:focus-visible,
a:focus-visible,
input:focus-visible,
textarea:focus-visible {
