    margin-left: 8px !important;
    margin-bottom: 8px !important;
  }
}

/* ==========================================================================
   5. CAPA DE PULIDO VISUAL — JERARQUÍA, COMPONENTES Y COHERENCIA
   Sólo presentación/UX: no añade funciones ni altera Media Center, widget,
   autenticación, llamadas ni modelo de datos.
   ========================================================================== */

/* --- 5.1 Jerarquía clara entre sidebar, conversación y panel de información --- */
@media (min-width: 1024px) {
  #sidebar-panel {
    border: 1px solid rgba(10, 26, 58, 0.07) !important;
    border-right: 1px solid rgba(197, 160, 89, 0.3) !important;
    box-shadow: 6px 0 20px rgba(10, 26, 58, 0.04);
  }

  #chat-panel {
    border: 1px solid rgba(197, 160, 89, 0.26) !important;
    box-shadow: 0 14px 38px rgba(10, 26, 58, 0.09), 0 1px 2px rgba(10, 26, 58, 0.05);
    z-index: 5;
  }

  #info-drawer-panel {
    border: 1px solid rgba(10, 26, 58, 0.07) !important;
    border-left: 1px solid rgba(197, 160, 89, 0.3) !important;
    box-shadow: -8px 0 28px rgba(10, 26, 58, 0.08);
  }
}

/* --- 5.2 Cabeceras de panel unificadas (sidebar + drawer) --- */
div.panel-head {
  min-height: 50px;
  background: linear-gradient(180deg, #FFFFFF 0%, #FBFCFE 100%);
  border-bottom-color: rgba(197, 160, 89, 0.22);
}

/* --- 5.3 Botones de icono unificados (misma caja, radio y elevación) --- */
button.icon-btn {
  border-radius: 12px;
  box-shadow: 0 1px 2px rgba(10, 26, 58, 0.05);
}
button.icon-btn:hover {
  transform: translateY(-1px);
  box-shadow: 0 5px 14px rgba(10, 26, 58, 0.12);
}
button.icon-btn:active {
  transform: translateY(0) scale(0.96);
}

#back-to-contacts-btn,
#back-to-contacts-btn:hover {
  box-shadow: none;
}

#back-to-contacts-btn:hover {
  background: rgba(197, 160, 89, 0.14);
}

/* --- 5.4 Cabecera de conversación: nombre, estado y acciones --- */
#chat-header-bar {
  min-height: 60px;
  background: rgba(255, 255, 255, 0.92);
  -webkit-backdrop-filter: blur(12px);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid rgba(197, 160, 89, 0.24);
  box-shadow: 0 1px 2px rgba(10, 26, 58, 0.04), 0 10px 22px -18px rgba(10, 26, 58, 0.55);
  gap: 10px;
}

#active-chat-name {
  letter-spacing: -0.015em;
}

#active-chat-id {
  background: var(--bg-card);
  border: 1px solid rgba(197, 160, 89, 0.22);
  border-radius: 999px;
  padding: 1px 8px;
  font-size: 10.5px;
  font-weight: 600;
  color: var(--text-secondary);
  max-width: 130px;
}

#active-chat-status {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-weight: 700;
  white-space: nowrap;
}

.status-dot {
  width: 7px;
  height: 7px;
  flex: 0 0 7px;
  border-radius: 50%;
  background: #94A3B8;
  display: inline-block;
}

.chat-header-status.is-online {
  color: var(--accent-tech);
}
.chat-header-status.is-online .status-dot {
  background: var(--accent-tech);
  box-shadow: 0 0 0 3px rgba(0, 114, 206, 0.15);
  animation: pulse-tech-glow 2.6s ease-in-out infinite;
}
.chat-header-status.is-offline {
  color: var(--text-secondary);
}
.chat-header-status.is-offline .status-dot {
  background: #CBD5E1;
}

#active-chat-avatar {
  width: 44px;
  height: 44px;
  box-shadow: 0 0 0 2px #FFFFFF, 0 0 0 3.5px rgba(197, 160, 89, 0.6), 0 6px 16px rgba(10, 26, 58, 0.16);
}

#active-chat-info-trigger:hover .chat-header-avatar {
  box-shadow: 0 0 0 2px #FFFFFF, 0 0 0 3.5px var(--accent-gold), 0 8px 20px rgba(10, 26, 58, 0.2);
}

/* --- 5.5 Hilo de conversación: ritmo, agrupación y metadatos --- */
#chat-messages {
  padding-top: 18px;
  padding-bottom: 20px;
  scroll-behavior: smooth;
}

#chat-messages > .msg-item + .msg-item {
  margin-top: 12px;
}

#chat-messages > .msg-item.msg-grouped {
  margin-top: 3px;
}

div.msg-meta {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 4px;
  padding: 0 4px;
  font-size: 11px;
  line-height: 1.3;
  color: var(--text-secondary);
}

div.msg-meta.msg-meta-sent {
  flex-direction: row-reverse;
}

div.msg-meta.msg-meta-grouped {
  margin-bottom: 2px;
}

.msg-meta-sender {
  font-weight: 700;
  letter-spacing: 0.01em;
  max-width: 160px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

div.msg-meta.msg-meta-received .msg-meta-sender {
  color: var(--text-secondary);
}

div.msg-meta.msg-meta-sent .msg-meta-sender {
  color: var(--accent-gold-dark);
}

.msg-meta-time {
  font-size: 10px;
  color: #94A3B8;
  letter-spacing: 0.02em;
}

/* En mensajes agrupados sólo se conserva la hora (evita ruido visual) */
div.msg-meta.msg-meta-grouped .msg-meta-sender {
  display: none;
}

/* --- 5.6 Burbujas: espaciado, legibilidad y jerarquía --- */
div.chat-bubble-inner {
  padding: 9px 13px 8px;
  border-radius: 16px;
  font-size: 14px;
  line-height: 1.55;
  max-width: 100%;
}

@media (min-width: 640px) {
  div.chat-bubble-inner {
    padding: 11px 15px 9px;
  }
}

.chat-bubble-sent {
  background: linear-gradient(165deg, #102550 0%, #0A1A3A 100%) !important;
  border: 1px solid rgba(197, 160, 89, 0.3) !important;
  border-top-right-radius: 6px !important;
  box-shadow: 0 3px 12px rgba(10, 26, 58, 0.2) !important;
}

.chat-bubble-received {
  background: var(--bg-bubble-other) !important;
  border: 1px solid rgba(197, 160, 89, 0.24) !important;
  border-top-left-radius: 6px !important;
  box-shadow: 0 2px 8px rgba(10, 26, 58, 0.07) !important;
}

.msg-text-content {
  font-family: var(--font-body);
  font-size: 14px;
  line-height: 1.6;
  letter-spacing: 0.005em;
}

/* Insignia de calidad sobre la imagen: se superpone en vez de comprimirla */
.chat-img-card .badge-hd,
.chat-img-card .badge-std {
  position: absolute;
  top: 8px;
  right: 8px;
  z-index: 2;
}

.chat-img-card .badge-std {
  background: linear-gradient(135deg, #0A1A3A 0%, #16305F 100%);
  color: #FFFFFF;
  font-family: var(--font-title);
  font-weight: 800;
  font-size: 10px;
  line-height: 1.2;
  padding: 2px 6px;
  border-radius: 6px;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.35);
}

/* Tarjetas claras anidadas en la burbuja enviada: el texto vuelve a oscuro para leerse */
.chat-bubble-sent .doc-card-container [class~="text-[#0A1A3A]"],
.chat-bubble-sent .link-preview-card [class~="text-[#0A1A3A]"],
.chat-bubble-sent .desktop-msg-toolbar [class~="text-[#0A1A3A]"],
.chat-bubble-sent button[class~="bg-[#C5A059]"] {
  color: #0A1A3A !important;
}

.chat-bubble-sent .doc-card-container [class~="text-[#64748B]"],
.chat-bubble-sent .link-preview-card [class~="text-[#64748B]"],
.chat-bubble-sent .desktop-msg-toolbar [class~="text-[#64748B]"] {
  color: #64748B !important;
}

.chat-bubble-sent .desktop-msg-toolbar button[class~="text-[#64748B]"]:hover {
  color: #C5A059 !important;
}

.chat-bubble-sent .link-preview-card p[class~="text-[#0A1A3A]"]:hover {
  color: #0072CE !important;
}

/* Enlaces de tarjetas claras: no heredan el azul reservado a los enlaces del texto */
.chat-bubble-inner .doc-card-container a {
  color: #FFFFFF !important;
}

.chat-bubble-inner .link-preview-card a {
  color: #0A1A3A !important;
}

.chat-bubble-received .chat-link,
.chat-bubble-received .chat-bubble-inner a {
  color: var(--accent-tech) !important;
  text-decoration-color: rgba(0, 114, 206, 0.4);
}

/* Pie de mensaje (copiar): visible siempre en táctil, sutil en escritorio */
.chat-bubble-inner .message-footer-bar {
  margin-top: 7px;
  padding-top: 5px;
  border-top: 1px solid rgba(255, 255, 255, 0.1);
  opacity: 0.6;
  transition: opacity 0.18s ease;
}

.chat-bubble-received .message-footer-bar {
  border-top-color: rgba(10, 26, 58, 0.08);
}

.chat-bubble-inner:hover .message-footer-bar {
  opacity: 1;
}

@media (hover: none) {
  .chat-bubble-inner .message-footer-bar {
    opacity: 1;
  }
}

.chat-bubble-inner .message-footer-bar button {
  font-size: 10.5px;
  font-weight: 600;
  padding: 2px 8px;
  border-radius: 8px;
  color: rgba(255, 255, 255, 0.72);
}

.chat-bubble-inner .message-footer-bar button:hover {
  background: rgba(255, 255, 255, 0.12);
  color: var(--accent-gold);
}

.chat-bubble-received .message-footer-bar button {
  color: var(--text-secondary);
}

.chat-bubble-received .message-footer-bar button:hover {
  background: rgba(197, 160, 89, 0.14);
  color: var(--accent-gold-dark);
}

/* Toolbar de acciones en hover */
div.desktop-msg-toolbar {
  gap: 2px;
  padding: 3px 7px;
  border-radius: 999px;
  box-shadow: 0 8px 22px rgba(10, 26, 58, 0.16);
}

.desktop-msg-toolbar button {
  font-size: 13px;
  padding: 2px 5px;
  border-radius: 8px;
}

.desktop-msg-toolbar button:hover {
  background: rgba(197, 160, 89, 0.14);
}

/* Píldora de reacciones */
div.reactions-wrapper:not(:empty) {
  background: #FFFFFF;
  border: 1px solid rgba(197, 160, 89, 0.4);
  border-radius: 999px;
  padding: 2px 7px;
  box-shadow: 0 4px 12px rgba(10, 26, 58, 0.14);
}

/* --- 5.7 Composer: campo, adjuntos, audio y envío --- */
#input-container {
  gap: 10px !important;
  border: 1px solid rgba(197, 160, 89, 0.26) !important;
  border-radius: 20px !important;
  box-shadow: 0 10px 30px rgba(10, 26, 58, 0.08), 0 1px 2px rgba(10, 26, 58, 0.04) !important;
}

#input-container:focus-within {
  border-color: var(--accent-gold) !important;
  box-shadow: 0 10px 30px rgba(10, 26, 58, 0.08), 0 0 0 3px var(--accent-gold-glow) !important;
}

#chat-textarea {
  font-size: 14px;
  line-height: 1.55;
  min-height: 44px;
  padding-top: 11px;
  padding-bottom: 11px;
}

#chat-textarea::placeholder {
  color: #94A3B8;
}

button.composer-btn {
  box-shadow: 0 1px 2px rgba(10, 26, 58, 0.06);
}

button.composer-btn:hover {
  transform: translateY(-1px);
  box-shadow: 0 5px 14px rgba(10, 26, 58, 0.12);
}

button.composer-btn:active {
