}

#send-btn:hover {
  box-shadow: 0 9px 22px rgba(153, 121, 61, 0.45), 0 1px 2px rgba(10, 26, 58, 0.18);
}

#reply-preview-bar {
  background: linear-gradient(90deg, rgba(197, 160, 89, 0.12) 0%, rgba(197, 160, 89, 0.04) 100%);
  border: 1px solid rgba(197, 160, 89, 0.28) !important;
  border-left: 4px solid var(--accent-gold) !important;
  border-radius: 12px;
}

#emoji-picker {
  border-radius: 18px;
  box-shadow: 0 20px 46px rgba(10, 26, 58, 0.18), 0 0 0 1px rgba(197, 160, 89, 0.18);
