}

#recording-bar {
  border-radius: 14px;
  box-shadow: 0 6px 18px rgba(220, 38, 38, 0.12);
}

/* --- 5.8 Estados vacíos y mensajes de error --- */
.empty-state {
  gap: 2px;
}

#chat-welcome .empty-state-icon {
  box-shadow: 0 10px 26px rgba(197, 160, 89, 0.2);
}

#chat-welcome .empty-state-title {
  letter-spacing: -0.015em;
}

#chat-welcome .empty-state-text {
  line-height: 1.6;
}

#contacts-list .empty-state-icon {
  margin-left: auto;
  margin-right: auto;
}

#contact-search-empty {
  animation: contact-search-empty-in 0.18s ease-out;
}

@keyframes contact-search-empty-in {
  from { opacity: 0; transform: translateY(4px); }
  to { opacity: 1; transform: none; }
}

.field-error {
  color: #B42318;
  background: #FEF3F2;
  border: 1px solid rgba(220, 38, 38, 0.18);
  border-radius: 10px;
  padding: 6px 9px;
  font-size: 11px;
  font-weight: 600;
  line-height: 1.4;
}

#drawer-media-content .media-empty,
.media-empty.media-empty {
  background: rgba(255, 255, 255, 0.75);
  border: 1px dashed rgba(197, 160, 89, 0.4);
