/* --- 5.9 Lista de contactos --- */
#contacts-list .contact-item {
  border: 1px solid transparent;
  border-radius: 12px;
  margin-bottom: 2px;
}

#contacts-list .contact-item:not(.is-active):hover {
  background: #FFFFFF;
  border-color: rgba(197, 160, 89, 0.28);
  box-shadow: 0 4px 14px rgba(10, 26, 58, 0.07);
}

#contacts-list .contact-item.is-active {
  border-color: rgba(197, 160, 89, 0.4);
  border-left: 4px solid var(--accent-gold);
}

/* --- 5.10 Panel de información (drawer) --- */
button.drawer-tab {
  font-weight: 700;
  border-radius: 9px;
}

button.drawer-tab.drawer-tab-active {
  box-shadow: 0 2px 8px rgba(10, 26, 58, 0.1);
}

div.drawer-contact-card {
  background: linear-gradient(180deg, #FFFFFF 0%, var(--bg-card) 100%);
  border-color: rgba(197, 160, 89, 0.26);
}

.drawer-specs > div {
  padding-bottom: 6px;
}

.drawer-specs > div:last-child {
  border-bottom: none;
  padding-bottom: 0;
}

/* --- 5.11 Barra superior de la aplicación --- */
header.sticky {
  box-shadow: 0 1px 0 rgba(10, 26, 58, 0.05), 0 10px 26px -22px rgba(10, 26, 58, 0.7);
}

/* --- 5.12 Responsive / móvil --- */
@media (max-width: 1023px) {
  #chat-panel {
    border: none !important;
    box-shadow: none !important;
  }

  #sidebar-panel {
    box-shadow: none;
  }

  #chat-messages {
    padding-top: 14px;
    padding-bottom: 16px;
  }

  #chat-header-bar {
    min-height: 56px;
    gap: 8px;
