  #chat-messages > .msg-item + .msg-item {
    margin-top: 10px;
  }

  div.chat-bubble-inner {
    font-size: 14px;
  }

  #normal-input-bar {
    gap: 6px;
  }

  #input-container {
    gap: 8px !important;
    border-radius: 18px !important;
  }

  #chat-textarea {
    min-height: 90px;
  }

  #active-chat-id {
    display: none;
  }
}

@media (pointer: coarse) {
  button.icon-btn {
    min-width: 40px;
    min-height: 40px;
  }

  .chat-bubble-inner .message-footer-bar {
    opacity: 1;
  }
}

/* ==========================================================================
   6. MONETIZACIÓN, BÓVEDA CIFRADA Y REPRODUCTOR DE VOZ WAVEFORM (SAAS SUITE)
   ========================================================================== */

/* 6.1 Reproductor de Audio Waveform Interactivo */
.audio-waveform-card {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 12px;
  border-radius: 16px;
