  background: linear-gradient(135deg, #C5A059, #99793D);
  color: #FFFFFF;
  box-shadow: 0 2px 8px rgba(197, 160, 89, 0.35);
  transition: transform 0.15s ease, filter 0.15s ease;
}
.waveform-play-btn:hover {
  transform: scale(1.05);
  filter: brightness(1.1);
}

.waveform-bars-container {
  display: flex;
  align-items: center;
  gap: 2.5px;
  height: 28px;
  flex: 1;
  cursor: pointer;
}

.waveform-bar {
  width: 3px;
  border-radius: 99px;
  background-color: rgba(10, 26, 58, 0.25);
  transition: height 0.1s ease, background-color 0.15s ease;
}
.is-local .waveform-bar {
  background-color: rgba(255, 255, 255, 0.35);
}

.waveform-bar.is-played {
  background-color: #C5A059;
}
.is-local .waveform-bar.is-played {
  background-color: #FDE68A;
}

.waveform-speed-badge {
  font-family: monospace;
  font-size: 10px;
  font-weight: 700;
  padding: 2px 6px;
  border-radius: 6px;
  background: rgba(197, 160, 89, 0.18);
  color: #99793D;
  border: 1px solid rgba(197, 160, 89, 0.35);
  cursor: pointer;
  transition: all 0.15s ease;
}
.is-local .waveform-speed-badge {
  background: rgba(255, 255, 255, 0.2);
  color: #FFFFFF;
  border-color: rgba(255, 255, 255, 0.3);
}

/* 6.2 Switcher de Espacios de Trabajo (Sidebar Segmented Control) */
.workspace-segmented-tab {
  flex: 1;
  text-align: center;
  padding: 6px 10px;
  font-size: 11px;
  font-weight: 700;
  border-radius: 10px;
  color: #64748B;
  transition: all 0.18s cubic-bezier(0.16, 1, 0.3, 1);
  cursor: pointer;
}
.workspace-segmented-tab.is-active {
  background-color: #FFFFFF;
  color: #0A1A3A;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.08);
  border: 1px solid rgba(197, 160, 89, 0.28);
}

/* 6.3 Tarjetas de Precios y Monetización */
.pricing-tier-card {
  border-radius: 20px;
  padding: 20px;
  border: 1px solid rgba(197, 160, 89, 0.22);
  background: #FFFFFF;
  transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;
  display: flex;
  flex-direction: column;
}
.pricing-tier-card:hover {
  transform: translateY(-2px);
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.06);
  border-color: #C5A059;
}
.pricing-tier-card.is-featured {
  border: 2px solid #C5A059;
  background: linear-gradient(180deg, #FFFDF8 0%, #FFFFFF 100%);
  position: relative;
  box-shadow: 0 8px 24px rgba(197, 160, 89, 0.16);
}

/* 6.4 Items de la Bóveda Cifrada */
.vault-item-card {
  padding: 14px;
  border-radius: 16px;
  background: #F8FAFC;
  border: 1px solid rgba(197, 160, 89, 0.2);
  transition: all 0.15s ease;
}
.vault-item-card:hover {
  background: #FFFFFF;
  border-color: #C5A059;
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.04);
}

/* 6.5 Canales de Equipo */
.channel-item {
  padding: 8px 12px;
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  cursor: pointer;
  transition: all 0.15s ease;
}
.channel-item:hover {
  background-color: #F8FAFC;
}
.channel-item.is-active {
  background-color: rgba(197, 160, 89, 0.12);
  border-left: 3px solid #C5A059;
  font-weight: 700;
}
